import java.util.*;

public class Main {
    static class Product { int id; String name; Product(int i, String n) { id = i; name = n; } }

    // A tiny model of a persistence context: identity map + snapshots
    static Map<Integer, Product> identity = new HashMap<>();
    static Map<Integer, String> snapshot = new HashMap<>();
    static int selects = 0;

    static Product find(int id) {
        Product p = identity.get(id);          // first-level cache hit?
        if (p == null) {
            selects++;                         // only now do we "hit the database"
            p = new Product(id, "Pen");
            identity.put(id, p);
            snapshot.put(id, p.name);          // loaded state copy
        }
        return p;
    }

    static int flush() {
        int updates = 0;
        for (Product p : identity.values()) {  // dirty checking: compare to snapshot
            if (!p.name.equals(snapshot.get(p.id))) { updates++; snapshot.put(p.id, p.name); }
        }
        return updates;
    }

    public static void main(String[] args) {
        Product a = find(1);
        Product b = find(1);
        System.out.println("same instance: " + (a == b) + ", selects: " + selects);
        a.name = "Pencil";                     // no save() call at all
        System.out.println("updates at flush: " + flush());
        System.out.println("updates at second flush: " + flush());
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        int n = 1000, props = 5;
        String[][] current = new String[n][props];
        String[][] snapshot = new String[n][props];
        for (int i = 0; i < n; i++)
            for (int j = 0; j < props; j++) { current[i][j] = "v" + j; snapshot[i][j] = "v" + j; }

        current[42][3] = "changed";            // only one field of one entity changes
        System.out.println("entities loaded: " + n + ", properties each: " + props);

        // Default dirty checking: compare every property of every entity, O(n * props)
        int comparisons = 0;
        List<Integer> dirty = new ArrayList<>();
        for (int i = 0; i < n; i++)
            for (int j = 0; j < props; j++) {
                comparisons++;
                if (!current[i][j].equals(snapshot[i][j])) { if (!dirty.contains(i)) dirty.add(i); }
            }
        System.out.println("default: " + comparisons + " comparisons, dirty entities " + dirty);

        // Enhancement-style tracking: a setter records the changed attribute, so flush reads a set
        Set<Integer> tracked = new HashSet<>(List.of(42));
        System.out.println("tracked: " + tracked.size() + " entity to inspect, 0 full comparisons");
    }
}

import java.util.*;

public class Main {
    static int queries = 0;
    static int[] orderIds() { queries++; int[] r = new int[50]; for (int i = 0; i < 50; i++) r[i] = i; return r; }

    public static void main(String[] args) {
        // Naive lazy loading: one query per order for customer, one per order for items
        queries = 0;
        int[] ids = orderIds();
        for (int id : ids) { queries++; queries++; }
        System.out.println("orders: " + ids.length + ", naive queries: " + queries);

        // Fix: fetch join for customer (1 query), batch size 25 for items (ceil(50/25) queries)
        queries = 0;
        ids = orderIds();
        queries++;                               // to-one fetch join folded into one SQL
        int batch = 25;
        queries += (ids.length + batch - 1) / batch;
        System.out.println("fetch join + batch size " + batch + ": " + queries + " queries");

        // Page ids first, then fetch graph by ids: 2 queries regardless of page size
        queries = 2;
        System.out.println("ids page + fetch by ids: " + queries + " queries");
    }
}

public class Main {
    public static void main(String[] args) {
        int owners = 50;                         // 50 orders, each with a lazy items collection
        System.out.println("owners loaded by the first query: " + owners);
        System.out.println("no fix (lazy):      " + (1 + owners) + " queries");
        for (int size : new int[] {10, 25, 100}) {
            int extra = (owners + size - 1) / size;   // ceil(owners / size)
            System.out.println("batch size " + size + ":  " + (1 + extra) + " queries");
        }
        // SUBSELECT: one extra query that reuses the original query as a subquery
        System.out.println("subselect:          2 queries (re-runs the original query inside)");
        // Fetch join: one SQL, but rows multiply: 50 orders x 4 items = 200 rows
        int items = 4;
        System.out.println("fetch join:         1 query, " + (owners * items) + " rows returned");
    }
}

public class Main {
    static boolean rollbackOnly = false;

    static void inner() {
        // The inner proxy joins the outer transaction, so it can only mark it rollback-only
        rollbackOnly = true;
        throw new RuntimeException("inner failed");
    }

    static void outer() {
        try {
            inner();
        } catch (RuntimeException e) {
            System.out.println("outer caught: " + e.getMessage());
        }
        // The outer proxy now tries to commit
        if (rollbackOnly) {
            throw new IllegalStateException("UnexpectedRollbackException: transaction marked rollback-only");
        }
        System.out.println("committed");
    }

    public static void main(String[] args) {
        try {
            outer();
        } catch (IllegalStateException e) {
            System.out.println("caller sees: " + e.getMessage());
        }
        System.out.println("rows saved: 0");
    }
}

public class Main {
    // One database row with a version column
    static int version = 1;
    static String name = "Pen";

    // UPDATE product SET name=?, version=version+1 WHERE id=1 AND version=?
    static synchronized boolean update(String newName, int expectedVersion) {
        if (version != expectedVersion) return false;   // 0 rows updated
        name = newName;
        version++;
        return true;
    }

    public static void main(String[] args) {
        int adminAVersion = version;            // both admins open the edit page at version 1
        int adminBVersion = version;
        System.out.println("A saves: " + update("Pencil", adminAVersion));
        System.out.println("B saves: " + update("Marker", adminBVersion) + " (conflict, 409)");
        System.out.println("row now: " + name + " v" + version);

        int fresh = version;                    // B reloads and re-applies the change
        System.out.println("B retries: " + update("Marker", fresh));
        System.out.println("row now: " + name + " v" + version);
    }
}

import java.util.*;

public class Main {
    static int stock = 5;

    // Same effect as: UPDATE item SET stock = stock - 1 WHERE id = ? AND stock > 0
    static synchronized boolean buyOne() {
        if (stock > 0) { stock--; return true; }
        return false;
    }

    public static void main(String[] args) throws Exception {
        int[] sold = new int[1];
        List<Thread> threads = new ArrayList<>();
        for (int i = 0; i < 20; i++) {
            Thread t = new Thread(() -> {
                if (buyOne()) { synchronized (sold) { sold[0]++; } }
            });
            threads.add(t);
            t.start();
        }
        for (Thread t : threads) t.join();
        System.out.println("buyers: 20, initial stock: 5");
        System.out.println("sold: " + sold[0] + ", stock left: " + stock);
    }
}

public class Main {
    static int roundTrips(int rows, int batchSize) { return (rows + batchSize - 1) / batchSize; }

    public static void main(String[] args) {
        int rows = 2_000_000;
        System.out.println("rows: " + rows);
        System.out.println("no batching (IDENTITY): " + roundTrips(rows, 1) + " round trips");
        System.out.println("batch_size 50:          " + roundTrips(rows, 50) + " round trips");

        // Why flush/clear matters: the context keeps every entity plus a snapshot
        int batch = 50;
        long managedNoClear = rows;             // all rows stay managed
        long managedWithClear = batch;          // cleared after each batch
        System.out.println("managed entities at the end, no clear: " + managedNoClear);
        System.out.println("managed entities with clear every " + batch + ": " + managedWithClear);
        long checkNoClear = 0;
        for (long m = 1; m <= rows; m += batch) checkNoClear += m;   // dirty check cost grows
        System.out.println("dirty-check visits, no clear: ~" + checkNoClear
            + " vs with clear: " + (long) (rows / batch) * batch);
    }
}
